    "\n      <div class=\"row\" style=\"align-items:flex-end;gap:18px;margin-bottom:12px\">\n        <div><label>目标</label><div><b><code>{0}</code></b></div></div>\n        <div><label>扫了</label><div>{1} 个</div></div>\n        <div><label>开着</label><div><b>{2}</b></div></div>\n        <div><label>关着</label><div>{3}</div></div>\n        <div><label>没回话</label><div>{4}</div></div>\n        <div><label>没路</label><div>{5}</div></div>\n      </div>\n      <div style=\"margin-bottom:12px\"><label>开着的端口</label><div>{6}</div></div>\n      {7}\n      <div style=\"background:{8};border:1px solid {9};border-radius:6px;padding:10px 12px;font-size:13.5px\">\n        {10}</div>\n      {11}\n      <p class=\"dim\" style=\"margin:10px 0 0\">{12}</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">原始结果</summary>\n        <pre class=\"dim\">{13}</pre></details>": "\n      <div class=\"row\" style=\"align-items:flex-end;gap:18px;margin-bottom:12px\">\n        <div><label>宛先</label><div><b><code>{0}</code></b></div></div>\n        <div><label>スキャン</label><div>{1} 件</div></div>\n        <div><label>開放</label><div><b>{2}</b></div></div>\n        <div><label>クローズ</label><div>{3}</div></div>\n        <div><label>応答なし</label><div>{4}</div></div>\n        <div><label>ルートなし</label><div>{5}</div></div>\n      </div>\n      <div style=\"margin-bottom:12px\"><label>開放中のポート</label><div>{6}</div></div>\n      {7}\n      <div style=\"background:{8};border:1px solid {9};border-radius:6px;padding:10px 12px;font-size:13.5px\">\n        {10}</div>\n      {11}\n      <p class=\"dim\" style=\"margin:10px 0 0\">{12}</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">生結果</summary>\n        <pre class=\"dim\">{13}</pre></details>",
    "\n      <div class=\"row\" style=\"align-items:flex-end;gap:18px;margin-bottom:12px\">\n        <div><label>目标</label><div><b><code>{0}</code></b></div></div>\n        {1}\n        <div><label>出口网卡</label><div>{2}</div></div>\n        <div><label>探测端口</label><div>{3}</div></div>\n        <div><label>靠哪一层测的</label><div>{4}</div></div>\n      </div>\n      {5}\n      {6}\n      <div style=\"background:{7};border:1px solid {8};border-radius:6px;padding:10px 12px;font-size:13.5px\">\n        {9}</div>\n      {10}\n      <p class=\"dim\" style=\"margin:10px 0 0\">{11}</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">原始结果</summary>\n        <pre class=\"dim\">{12}</pre></details>": "\n      <div class=\"row\" style=\"align-items:flex-end;gap:18px;margin-bottom:12px\">\n        <div><label>対象</label><div><b><code>{0}</code></b></div></div>\n        {1}\n        <div><label>送信側アダプタ</label><div>{2}</div></div>\n        <div><label>プローブ先ポート</label><div>{3}</div></div>\n        <div><label>どの層で測定</label><div>{4}</div></div>\n      </div>\n      {5}\n      {6}\n      <div style=\"background:{7};border:1px solid {8};border-radius:6px;padding:10px 12px;font-size:13.5px\">\n        {9}</div>\n      {10}\n      <p class=\"dim\" style=\"margin:10px 0 0\">{11}</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">生の結果</summary>\n        <pre class=\"dim\">{12}</pre></details>",
    "\n      <div class=\"row\" style=\"align-items:flex-end;gap:18px;margin-bottom:12px\">\n        <div><label>这台自称</label><div><b>{0}</b>\n          {1}</div></div>\n        {2}\n        {3}\n      </div>{4}": "\n      <div class=\"row\" style=\"align-items:flex-end;gap:18px;margin-bottom:12px\">\n        <div><label>この機器の自己申告</label><div><b>{0}</b>\n          {1}</div></div>\n        {2}\n        {3}\n      </div>{4}",
    "\n      <div class=\"row\" style=\"gap:18px;margin-bottom:10px;flex-wrap:wrap\">\n        <div><label>目标</label><div><b><code>{0}</code></b> {1}</div></div>\n        <div><label>间隔 / 时长</label><div>{2}ms · {3}s</div></div>\n        <div><label>实到</label><div>{4}s\n          {5}</div></div>\n      </div>\n      {6}\n      {7}\n      {8}{9}{10}{11}\n      <div style=\"margin-top:14px;background:{12};border:1px solid {13};border-radius:6px;\n        padding:10px 12px;font-size:13.5px\">{14}</div>\n      <p class=\"dim\" style=\"margin:10px 0 0\">{15}</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">原始结果（逐发留痕）</summary>\n        <pre class=\"dim\">{16}</pre></details>": "\n      <div class=\"row\" style=\"gap:18px;margin-bottom:10px;flex-wrap:wrap\">\n        <div><label>対象</label><div><b><code>{0}</code></b> {1}</div></div>\n        <div><label>間隔 / 送信数</label><div>{2}ms · {3}s</div></div>\n        <div><label>実際に到達</label><div>{4}s\n          {5}</div></div>\n      </div>\n      {6}\n      {7}\n      {8}{9}{10}{11}\n      <div style=\"margin-top:14px;background:{12};border:1px solid {13};border-radius:6px;\n        padding:10px 12px;font-size:13.5px\">{14}</div>\n      <p class=\"dim\" style=\"margin:10px 0 0\">{15}</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">生の結果（送信ごとの記録）</summary>\n        <pre class=\"dim\">{16}</pre></details>",
    "\n      <div style=\"background:{0};border:1px solid {1};border-radius:6px;padding:10px 12px;font-size:13.5px\">\n        {2}\n        {3}\n      </div>\n      <p class=\"dim\" style=\"margin:10px 0 0\">{4}</p>\n      <table style=\"margin-top:12px\">\n        <tr><th></th><th>按排查顺序</th><th>问了什么</th><th>状态</th><th>判定</th><th>依据</th></tr>\n        {5}\n      </table>\n      <p class=\"hint\" style=\"margin-top:10px\">★ 一共问了 {6} 步。状态写成「没问出去」或「没问到这一步」的那些，\n        就是这份结论的边界 —— 想让它们也问出结果，把「目标」填实，或者去高级里把时间调够。</p>\n      <p class=\"hint\" style=\"margin-top:6px\">每一步的判定用的就是那一页同一个工具的判定，话术一份都没有重写。\n        想单独把某一步问细，去下面「出问题了」以外的对应页。</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">原始结果</summary>\n        <pre class=\"dim\">{7}</pre></details>": "\n      <div style=\"background:{0};border:1px solid {1};border-radius:6px;padding:10px 12px;font-size:13.5px\">\n        {2}\n        {3}\n      </div>\n      <p class=\"dim\" style=\"margin:10px 0 0\">{4}</p>\n      <table style=\"margin-top:12px\">\n        <tr><th></th><th>切り分け順</th><th>何を照会</th><th>状態</th><th>判定</th><th>根拠</th></tr>\n        {5}\n      </table>\n      <p class=\"hint\" style=\"margin-top:10px\">★ 合計 {6} ステップ照会した。状態が「未照会」か「このステップまで照会できず」になっているものは、\n        この結論の境界——結果を出させたいなら「宛先」を埋めるか、詳細設定で時間を十分に取る。</p>\n      <p class=\"hint\" style=\"margin-top:6px\">各ステップの判定は、そのページの同一ツールの判定そのもの。言い回しは一切書き直していない。\n        1 ステップを単独で細かく聞きたいなら、以下の「問題あり」以外の対応ページへ。</p>\n      <details style=\"margin-top:10px\"><summary class=\"dim\">生の結果</summary>\n        <pre class=\"dim\">{7}</pre></details>",
